import React, { useState, useEffect, useMemo } from 'react';
import { useTable, useSortBy } from 'react-table';
import { searchTracks, getTrackDetails, searchSimilarTracks } from '../services/api';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';

const TrackSearch = ({ searchTerm }) => {
  const [tracks, setTracks] = useState([]);
  const [isFetchingSimilar, setIsFetchingSimilar] = useState(false);
  const [contextMenu, setContextMenu] = useState(null); // State for the context menu

  useEffect(() => {
    if (searchTerm) {
      searchTracks(searchTerm).then(setTracks).catch((error) => {
        console.error('Error fetching tracks:', error);
      });
    }
  }, [searchTerm]);

  const handleRightClick = (trackId, event) => {
    event.preventDefault(); // Prevent default context menu
    setContextMenu({ trackId, x: event.clientX, y: event.clientY }); // Set custom context menu position
  };

  const handleGetSimilarTracks = async (trackId) => {
    setIsFetchingSimilar(true);
    setContextMenu(null); // Hide context menu

    try {
      const trackDetails = await getTrackDetails(trackId);
      const criteria = {
        genre: trackDetails.genre,
        tempo: trackDetails.tempo,
        artist: trackDetails.artist,
        key: trackDetails.key,
        danceability: trackDetails.danceability,
        timeSignature: trackDetails.time_signature,
      };

      const similarTracks = await searchSimilarTracks(criteria);
      setTracks(similarTracks); // Replace table data with similar tracks
    } catch (error) {
      console.error('Error fetching similar tracks:', error);
    } finally {
      setIsFetchingSimilar(false);
    }
  };

  // Hide context menu on click outside
  const handleClickOutside = () => {
    if (contextMenu) setContextMenu(null);
  };

  useEffect(() => {
    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, [contextMenu]);

  const columns = useMemo(() => [
    { Header: 'Track Name', accessor: 'name' },
    { Header: 'Artist Name', accessor: 'artists[0].name' },
    { Header: 'Album Name', accessor: 'album.name' },
    { Header: 'Release Date', accessor: 'album.release_date', Cell: ({ value }) => value ? value.split('-')[0] : 'Unknown' },
    { Header: 'Preview', accessor: 'id', Cell: ({ value }) => value ? (
        <iframe
          src={`https://open.spotify.com/embed/track/${value}`}
          width="100%"
          height="80"
          allow="encrypted-media"
          style={{ border: 'none' }}
        ></iframe>
      ) : 'No Preview'
    },
  ], []);

  const data = useMemo(() => tracks, [tracks]);
  const { getTableProps, getTableBodyProps, headerGroups, rows, prepareRow } = useTable({ columns, data }, useSortBy);

  return (
    <div>
      {isFetchingSimilar && <p>Fetching similar tracks...</p>}
      <table {...getTableProps()} style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse' }} className="results-table">
        <thead>
          {headerGroups.map(headerGroup => (
            <tr {...headerGroup.getHeaderGroupProps()} style={{ backgroundColor: '#00b4db', color: 'white' }}>
              {headerGroup.headers.map(column => (
                <th {...column.getHeaderProps(column.getSortByToggleProps())} style={{ padding: '10px', borderBottom: '1px solid #ddd' }}>
                  {column.render('Header')}
                  {column.isSorted ? (column.isSortedDesc ? <ArrowDownwardIcon /> : <ArrowUpwardIcon />) : null}
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody {...getTableBodyProps()}>
          {rows.map((row, index) => {
            prepareRow(row);
            return (
              <tr
                {...row.getRowProps()}
                onContextMenu={(e) => handleRightClick(row.original.id, e)}
                style={{
                  backgroundColor: index % 2 === 0 ? '#f9f9f9' : 'white',
                  color: '#606060',
                  fontFamily: 'Arial, sans-serif',
                  borderBottom: '1px solid #ddd',
                  cursor: 'context-menu'
                }}
              >
                {row.cells.map(cell => (
                  <td {...cell.getCellProps()} style={{ padding: '10px', borderBottom: '1px solid #ddd' }}>
                    {cell.render('Cell')}
                  </td>
                ))}
              </tr>
            );
          })}
        </tbody>
      </table>

      {/* Custom context menu */}
      {contextMenu && (
        <div
          style={{
            position: 'absolute',
            top: contextMenu.y,
            left: contextMenu.x,
            backgroundColor: 'white',
            boxShadow: '0px 0px 6px rgba(0,0,0,0.2)',
            padding: '8px',
            borderRadius: '4px',
            zIndex: 1000,
          }}
          onClick={() => handleGetSimilarTracks(contextMenu.trackId)}
        >
          <p style={{ margin: 0, color: '#333', cursor: 'pointer' }}>Get Similar Tracks</p>
        </div>
      )}
    </div>
  );
};

export default TrackSearch;
